WITH base AS (SELECT *, TRIM(channel) AS clean_channel FROM promotions WHERE ends_on > DATE '2024-03-28') SELECT *, ROW_NUMBER() OVER (PARTITION BY channel, promo_code ORDER BY discount_pct DESC, id) AS row_seq, AVG(discount_pct) OVER (PARTITION BY promo_code) AS promo_code_avg_discount_pct, SUM(discount_pct) OVER (PARTITION BY promo_code ORDER BY ends_on, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_discount_pct FROM base;
